INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Netzwerkprotokoll immer Daten überträgt?', 2, '[{"text": "Nein", "correct": true, "because": "Es dient der Steuerung"}, {"text": "Ja", "correct": false, "because": "Nicht primär für Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool nutzt ein Protokoll zur Fehlerdiagnose?', 3, '[{"text": "Ping", "correct": true, "because": "Testet Erreichbarkeit"}, {"text": "FTP", "correct": false, "because": "Dateiübertragung"}, {"text": "HTTP", "correct": false, "because": "Webprotokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen hat ein Steuerprotokoll im Netzwerk?', 5, '[{"text": "Fehlermeldung", "correct": true, "because": "Signalisiert Probleme"}, {"text": "Diagnose", "correct": true, "because": "Prüft Verbindungen"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht seine Aufgabe"}, {"text": "Dateitransfer", "correct": false, "because": "Anderes Protokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es läuft auf Schicht 3. b) Es überträgt Nutzdaten wie TCP.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine Nutzdaten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine Netzwerkverbindung teste?', 4, '[{"text": "Echo-Anfrage", "correct": false, "because": "Teil der Diagnose"}, {"text": "Fehlermeldungen", "correct": false, "because": "Wichtig für Analyse"}, {"text": "Routerfarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass dieses Protokoll immer aktiv ist. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Läuft im Hintergrund"}, {"text": "Nein", "correct": false, "because": "Immer verfügbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachricht zeigt an, dass ein Ziel nicht erreichbar ist?', 3, '[{"text": "Destination Unreachable", "correct": true, "because": "Meldet Netzwerkfehler"}, {"text": "Echo Reply", "correct": false, "because": "Antwort auf Ping"}, {"text": "Time Exceeded", "correct": false, "because": "Zeitüberschreitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rollen spielt ein Steuerprotokoll?', 5, '[{"text": "Fehlerberichterstattung", "correct": true, "because": "Informiert über Probleme"}, {"text": "Verbindungsprüfung", "correct": true, "because": "Testet Erreichbarkeit"}, {"text": "Datenkompression", "correct": false, "because": "Nicht seine Funktion"}, {"text": "Authentifizierung", "correct": false, "because": "Andere Protokolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) es mit Ping arbeitet und b) es Daten verschlüsselt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine Verschlüsselung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um eine Verbindung zu testen?', 4, '[{"text": "Echo Request", "correct": false, "because": "Startet Diagnose"}, {"text": "IP-Adresse", "correct": false, "because": "Ziel erforderlich"}, {"text": "Monitorgröße", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann dieses Protokoll Datenverluste verhindern?', 2, '[{"text": "Nein", "correct": true, "because": "Nur meldet, nicht verhindert"}, {"text": "Ja", "correct": false, "because": "Keine Korrektur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Diagnoseprotokoll?', 4, '[{"text": "Schnelle Fehlererkennung", "correct": true, "because": "Identifiziert Probleme"}, {"text": "Latenzmessung", "correct": true, "because": "Misst Antwortzeit"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass es nur für Router wichtig ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Für alle Netzwerkgeräte"}, {"text": "Ja", "correct": false, "because": "Universell genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Echo-Anfrage?', 3, '[{"text": "Erreichbarkeit prüfen", "correct": true, "because": "Testet Verbindung"}, {"text": "Daten übertragen", "correct": false, "because": "Nicht dafür gedacht"}, {"text": "Netzwerk sichern", "correct": false, "because": "Keine Sicherheitsfunktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es meldet Zeitüberschreitungen. b) Es ersetzt TCP.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "TCP ist eigenständig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachricht zeigt ein Routing-Problem?', 4, '[{"text": "Time Exceeded", "correct": true, "because": "Zeigt Schleifen oder Ausfälle"}, {"text": "Echo Reply", "correct": false, "because": "Nur Antwort"}, {"text": "Parameter Problem", "correct": false, "because": "Anderer Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Traceroute dieses Protokoll nutzt?', 2, '[{"text": "Ja", "correct": true, "because": "Verfolgt Pfad mit ICMP"}, {"text": "Nein", "correct": false, "because": "Traceroute basiert darauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen ein Steuerprotokoll nützlich?', 5, '[{"text": "Fehlerlokalisierung", "correct": true, "because": "Findet Problemstellen"}, {"text": "Verfügbarkeitsprüfung", "correct": true, "because": "Testet Geräte"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Faktor"}, {"text": "Datenkompression", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist es für alle Netzwerke Pflicht?', 3, '[{"text": "Ja", "correct": true, "because": "Teil von IP"}, {"text": "Nein", "correct": false, "because": "Aber universell genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu diesem Protokoll?', 4, '[{"text": "Verbindungstest", "correct": true, "because": "Ping nutzt es"}, {"text": "Dateiübertragung", "correct": false, "because": "Andere Protokolle"}, {"text": "Webseitenaufbau", "correct": false, "because": "HTTP zuständig"}]');
